14	/// Why the MHPCO refuses to quote a premium at all.
15	#[derive(Debug)]
16	pub enum QuoteError {
17	    /// The catalogue lists no item of this type.
18	    UnknownItemType { item_type: String },
19	}
20	
21	impl std::fmt::Display for QuoteError {
22	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
23	        match self {
24	            Self::UnknownItemType { item_type } => {
25	                write!(formatter, "the MHPCO does not insure a {item_type}")
26	            }
27	        }
28	    }
29	}
30	
31	/// Why the MHPCO refuses to settle a claim at all.
32	#[derive(Debug)]
33	pub enum ClaimError {
34	    /// A damage was reported with a negative amount.
35	    NegativeDamageAmount { amount: i64 },
36	    /// The policy covers no item of this type at all.
37	    ItemNotInsured { item_type: String },
38	    /// More damages of this item type were reported than the policy covers.
39	    MoreDamagesThanInsuredItems { item_type: String },
40	}
41	
42	impl std::fmt::Display for ClaimError {
43	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
44	        match self {
45	            Self::NegativeDamageAmount { amount } => {
46	                write!(formatter, "a damage amount of {amount} is not a loss")
47	            }
48	            Self::ItemNotInsured { item_type } => {
49	                write!(formatter, "the damaged {item_type} is not insured by this policy")
50	            }
51	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
52	                formatter,
53	                "more {item_type} damages were reported than the policy insures"
54	            ),
55	        }
56	    }
57	}
