59	/// What the MHPCO settles on a claim: the payout and the cap left on the
60	/// policy afterwards.
61	#[derive(Debug)]
62	pub struct ClaimResult {
63	    pub payout: u64,
64	    pub remaining_cap: u64,
65	}
66	
67	/// The single customer a scenario is quoted for.
68	pub struct Customer {
69	    pub years_with_mhpco: u32,
70	}
71	
72	pub struct Item {
73	    pub item_type: String,
74	    pub material: String,
75	    pub enchantment: u32,
76	    pub cursed: bool,
77	}
78	
79	const PROCESSING_FEE: u64 = 5;
80	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
81	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
82	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
83	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
84	
85	const COMPONENT_INSURANCE_VALUE: u64 = 250;
86	const COMPONENT_BASE_PREMIUM: u64 = 25;
87	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
88	const COMPONENT_BLOCK_SIZE: usize = 3;
89	const CURSE_SURCHARGE_PERCENT: u64 = 50;
90	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
91	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
92	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
93	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
94	const LOYALTY_YEARS: u32 = 2;
95	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
96	
97	/// Components, such as runes and moonstones, are the parts the MHPCO insures
98	/// alongside main items and the only items the building-block offer covers.
99	fn is_component(item: &Item) -> bool {
100	    matches!(item.item_type.as_str(), "rune" | "moonstone")
101	}
102	
103	/// What the MHPCO price list says about one main item: the value it is insured
104	/// for and the base premium it costs to insure. The list states both figures on
105	/// one line per item, and the office never learns one without the other.
106	struct PriceListEntry {
107	    insurance_value: u64,
108	    base_premium: u64,
109	}
110	
111	/// The MHPCO price list for main items, or nothing at all when the catalogue
112	/// does not list that type. This is the one place the roster of insurable main
113	/// items is written down: being listed here is what it means for the office to
114	/// insure a type.
115	fn price_list_entry(item_type: &str) -> Option<PriceListEntry> {
116	    let (insurance_value, base_premium) = match item_type {
117	        "sword" => (1000, 100),
118	        "amulet" => (600, 60),
119	        "staff" => (800, 80),
120	        "potion" => (400, 40),
121	        _ => return None,
122	    };
123	    Some(PriceListEntry {
124	        insurance_value,
125	        base_premium,
126	    })
127	}
128	
129	/// The MHPCO insures the components it recognises and the main items its price
130	/// list names; it insures nothing else.
131	fn is_in_catalogue(item: &Item) -> bool {
132	    is_component(item) || price_list_entry(&item.item_type).is_some()
133	}
134	
135	/// A reported damage must be a loss, never a negative amount.
136	fn check_every_damage_amount_is_a_loss(incident: &Incident) -> Result<(), ClaimError> {
137	    match incident.damages.iter().find(|damage| damage.amount < 0) {
138	        Some(negative) => Err(ClaimError::NegativeDamageAmount {
139	            amount: negative.amount,
140	        }),
141	        None => Ok(()),
142	    }
143	}
144	
145	/// The MHPCO can only price the items its catalogue lists.
146	fn check_every_item_is_in_the_catalogue(items: &[Item]) -> Result<(), QuoteError> {
147	    match items.iter().find(|item| !is_in_catalogue(item)) {
148	        Some(unknown) => Err(QuoteError::UnknownItemType {
149	            item_type: unknown.item_type.clone(),
150	        }),
151	        None => Ok(()),
152	    }
153	}
154	
155	/// The price-list line a main item is priced and insured by. The catalogue
156	/// guard has already refused anything the list does not name, so a main item
157	/// the office has accepted is always listed.
158	fn listed(item: &Item) -> PriceListEntry {
159	    price_list_entry(&item.item_type).expect("the catalogue lists this item type")
160	}
161	
162	/// The base premium one insured item earns. Every component is priced alike;
163	/// a main item is priced by its price-list line.
164	fn base_premium(item: &Item) -> u64 {
165	    if is_component(item) {
166	        return COMPONENT_BASE_PREMIUM;
167	    }
168	    listed(item).base_premium
169	}
170	
171	/// The building-block offer is reserved for a group of exactly 3 alike
172	/// components; a larger group does not qualify, it is priced per component.
173	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
174	    alike_component_count == COMPONENT_BLOCK_SIZE
175	}
176	
177	/// The price the MHPCO charges for one group of alike components: the
178	/// building-block offer when the group qualifies, otherwise per component.
179	fn component_group_base_premium(count: usize) -> u64 {
180	    if qualifies_as_building_block(count) {
181	        COMPONENT_BLOCK_BASE_PREMIUM
182	    } else {
183	        count as u64 * COMPONENT_BASE_PREMIUM
184	    }
185	}
186	
187	/// How many entries fall under each key a list of items is grouped by. The
188	/// MHPCO tallies items this way wherever a rule counts like with like: the
189	/// claim side groups by catalogue type to match damages against cover, the
190	/// premium side by alike-group key to recognise a building block.
191	fn count_by_item_type<'a>(
192	    item_types: impl Iterator<Item = &'a str>,
193	) -> BTreeMap<&'a str, usize> {
194	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
195	    for item_type in item_types {
196	        *counts.entry(item_type).or_insert(0) += 1;
197	    }
198	    counts
199	}
200	
201	/// Two components are "alike" when they share this key. For the MHPCO,
202	/// alike means the very same catalogue type: a rune and a moonstone are
203	/// never alike, so mixed component types form no building block.
204	fn alike_group_key(item: &Item) -> &str {
205	    &item.item_type
206	}
207	
208	/// The policy base premium: the sum of all insured items' base premiums,
209	/// with alike components priced per group so a block can be recognised.
210	fn policy_base_premium(items: &[Item]) -> u64 {
211	    let main_items_total: u64 = items
212	        .iter()
213	        .filter(|item| !is_component(item))
214	        .map(base_premium)
215	        .sum();
216	
217	    let alike_component_groups = count_by_item_type(
218	        items
219	            .iter()
220	            .filter(|item| is_component(item))
221	            .map(alike_group_key),
222	    );
223	
224	    main_items_total
225	        + alike_component_groups
226	            .values()
227	            .map(|count| component_group_base_premium(*count))
228	            .sum::<u64>()
229	}
230	
231	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
232	#[derive(Clone, Copy)]
233	enum Debtor {
234	    Customer,
235	    Mhpco,
236	}
237	
238	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
239	/// settles the direction by itself once it is known who owes whom: an amount
240	/// the customer owes is rounded up, an amount the office owes is rounded down.
241	/// Intermediate amounts stay fractional; only the final amount is rounded.
242	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
243	    match owed_by {
244	        Debtor::Customer => amount.ceil() as u64,
245	        Debtor::Mhpco => amount.floor() as u64,
246	    }
247	}
248	
249	/// A policy-wide modifier is measured against the policy base premium, the
250	/// sum of all item base premiums, never against a single item.
251	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
252	    policy_base_premium * percent as f64 / 100.0
253	}
254	
255	/// Every item in a quote is treated as a first insurance, so the initial
256	/// assessment surcharge is charged on the whole policy base premium.
257	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
258	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
259	}
260	
261	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
262	/// highly enchanted. This is the premium-side threshold; the claim-side
263	/// reimbursement clause judges enchantment by its own, stricter threshold.
264	fn is_highly_enchanted(item: &Item) -> bool {
265	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
266	}
267	
268	/// An item-specific risk surcharge is charged on the base premium of the
269	/// affected item, never on the policy total.
270	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
271	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
272	}
273	
274	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
275	/// item that brings two of them is surcharged for each.
276	fn item_risk_surcharge(item: &Item) -> f64 {
277	    let mut surcharge = 0.0;
278	    if item.cursed {
279	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
280	    }
281	    if is_highly_enchanted(item) {
282	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
283	    }
284	    surcharge
285	}
286	
287	/// Item-specific modifiers apply to the base premium of the affected item,
288	/// never to the policy total, so the policy owes the sum of the items' own
289	/// risk surcharges.
290	fn item_risk_surcharges(items: &[Item]) -> f64 {
291	    items.iter().map(item_risk_surcharge).sum()
292	}
293	
294	/// A long-standing customer, with at least two years of business with the
295	/// MHPCO, has earned the loyalty discount.
296	fn is_long_standing(customer: &Customer) -> bool {
297	    customer.years_with_mhpco >= LOYALTY_YEARS
298	}
299	
300	/// The loyalty discount is a policy-wide modifier, so it is measured against
301	/// the policy base premium.
302	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
303	    if is_long_standing(customer) {
304	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
305	    } else {
306	        0.0
307	    }
308	}
309	
310	/// A contract is a follow-up when the customer already holds at least one
311	/// other contract with the MHPCO; the customer's very first is not.
312	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
313	    contracts_already_held > 0
314	}
315	
316	/// Every contract after the customer's first earns the follow-up discount. It
317	/// is a policy-wide modifier, so it is measured against the policy base premium.
318	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
319	    if is_follow_up_contract(contracts_already_held) {
320	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
321	    } else {
322	        0.0
323	    }
324	}
325	
326	/// What the customer's standing with the MHPCO adds to or takes off the policy
327	/// base premium: the net of every policy-wide surcharge and discount. Positive
328	/// amounts raise the premium, negative amounts lower it.
329	fn policy_wide_modifiers(
330	    customer: &Customer,
331	    contracts_already_held: u32,
332	    policy_base_premium: f64,
333	) -> f64 {
334	    first_insurance_surcharge(policy_base_premium)
335	        - loyalty_discount(customer, policy_base_premium)
336	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
337	}
338	
339	/// The premium the policy earns before the processing fee: the policy base
340	/// premium, plus what the items' own risks cost, plus what the customer's
341	/// standing adjusts.
342	fn modified_policy_premium(
343	    customer: &Customer,
344	    contracts_already_held: u32,
345	    items: &[Item],
346	) -> f64 {
347	    let policy_base_premium = policy_base_premium(items) as f64;
348	    policy_base_premium
349	        + item_risk_surcharges(items)
350	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
351	}
352	
353	/// The MHPCO adds its processing fee to every premium at the very end, after
354	/// every surcharge and discount has been settled.
355	pub fn quote_premium(
356	    customer: &Customer,
357	    contracts_already_held: u32,
358	    items: &[Item],
359	) -> Result<u64, QuoteError> {
360	    check_every_item_is_in_the_catalogue(items)?;
361	    Ok(rounded_in_mhpco_favor(
362	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
363	        Debtor::Customer,
364	    ))
365	}
366	
367	/// Damage to a very highly enchanted item is reimbursed at only half the
368	/// damage amount. This claim-side threshold is deliberately stricter than, and
369	/// separate from, the premium-side high-enchantment risk surcharge: an item can
370	/// be enchanted enough to cost more to insure yet not enough to be halved.
371	fn is_reimbursed_by_half(item: &Item) -> bool {
372	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
373	}
374	
375	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
376	/// before the deductible is taken off. Full reimbursement is the MHPCO's
377	/// standing position: it is both what an item with no clause receives and what
378	/// the dragon-material clause prescribes, so that clause asks for no share of
379	/// its own. Only the halving clause departs from full reimbursement, and it
380	/// wins wherever it applies.
381	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
382	    if is_reimbursed_by_half(damaged_item) {
383	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
384	    } else {
385	        damage.amount as f64
386	    }
387	}
388	
389	/// The deductible applies per damage event, after the reimbursement clauses.
390	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
391	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
392	}
393	
394	/// Which insured item a reported damage refers to. A damage names only a
395	/// catalogue type, so the policy is searched for an item of that type; the
396	/// reimbursement clauses are judged against the item found here, not the report.
397	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
398	    items
399	        .iter()
400	        .find(|item| item.item_type == damage.item_type)
401	        .expect("the damaged item is insured by this policy")
402	}
403	
404	/// What the MHPCO owes for an incident filed against a policy: the sum of the
405	/// reimbursements its damages earn, rounded in the office's favor at the end.
406	pub fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
407	    let total: f64 = incident
408	        .damages
409	        .iter()
410	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
411	        .sum();
412	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
413	}
414	
415	/// What one insured item is insured for. Every component is insured alike; a
416	/// main item is insured for the value its price-list line names.
417	fn insurance_value(item: &Item) -> u64 {
418	    if is_component(item) {
419	        return COMPONENT_INSURANCE_VALUE;
420	    }
421	    listed(item).insurance_value
422	}
423	
424	/// The insurance sum of a policy is the sum of its items' insurance values.
425	fn insurance_sum(items: &[Item]) -> u64 {
426	    items.iter().map(insurance_value).sum()
427	}
428	
429	/// The total payout per policy is capped at twice the insurance sum.
430	fn policy_cap(items: &[Item]) -> u64 {
431	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
432	}
433	
434	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
435	/// but never more than the cap the policy has left, and reports the cap that
436	/// survives the payout.
437	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
438	    let payout = earned.min(available_cap);
439	    ClaimResult {
440	        payout,
441	        remaining_cap: available_cap - payout,
442	    }
443	}
444	
445	/// How much of its cap a policy still has to pay out with, once earlier claims
446	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
447	/// exhausted cap is simply nothing left, never a debt the policy owes back.
448	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
449	    policy_cap(items).saturating_sub(cap_already_consumed)
450	}
451	
452	/// How many items of a catalogue type a policy insures. A type the policy never
453	/// mentions is insured none of: the MHPCO holds no cover for what it did not
454	/// write down.
455	fn insured_count_of(insured_counts: &BTreeMap<&str, usize>, item_type: &str) -> usize {
456	    insured_counts.get(item_type).copied().unwrap_or(0)
457	}
458	
459	/// Every reported damage must be covered by an insured item of its own. The
460	/// office compares the damages it was sent against the policy type by type, so a
461	/// type damaged twice needs two insured items of that type to stand. One
462	/// comparison decides admissibility; how far it falls short decides which
463	/// refusal the claim earns -- a type the policy does not cover at all is refused
464	/// as uninsured, a type covered by too few items as an over-count.
465	fn check_policy_covers_every_damage(
466	    items: &[Item],
467	    incident: &Incident,
468	) -> Result<(), ClaimError> {
469	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
470	    for (item_type, reported) in
471	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
472	    {
473	        let insured_of_that_type = insured_count_of(&insured, item_type);
474	        if insured_of_that_type == 0 {
475	            return Err(ClaimError::ItemNotInsured {
476	                item_type: item_type.to_string(),
477	            });
478	        }
479	        if reported > insured_of_that_type {
480	            return Err(ClaimError::MoreDamagesThanInsuredItems {
481	                item_type: item_type.to_string(),
482	            });
483	        }
484	    }
485	    Ok(())
486	}
487	
488	/// What the MHPCO settles on an incident filed against a policy: what the
489	/// incident earns, limited by the cap the policy has left. The office first
490	/// satisfies itself that the claim is admissible at all; an inadmissible claim
491	/// is refused whole, and nothing is paid out on it.
492	pub fn claim(
493	    items: &[Item],
494	    incident: &Incident,
495	    cap_already_consumed: u64,
496	) -> Result<ClaimResult, ClaimError> {
497	    check_every_damage_amount_is_a_loss(incident)?;
498	    check_policy_covers_every_damage(items, incident)?;
499	    Ok(settled_within_cap(
500	        claim_payout(items, incident),
501	        cap_remaining_on(items, cap_already_consumed),
502	    ))
503	}
504	
505	#[cfg(test)]
506	mod tests {
507	    use super::*;
508	
509	    /// A customer with the given number of years of business with the MHPCO,
510	    /// the standing the loyalty discount is judged against.
511	    fn customer_of(years_with_mhpco: u32) -> Customer {
512	        Customer { years_with_mhpco }
513	    }
514	
515	    /// A customer in their first year of business with the MHPCO.
516	    fn newcomer() -> Customer {
517	        customer_of(0)
518	    }
519	
520	    /// A plain, unenchanted, uncursed item of the given catalogue type.
521	    fn plain(item_type: &str) -> Item {
522	        Item {
523	            item_type: item_type.to_string(),
524	            material: "steel".to_string(),
525	            enchantment: 0,
526	            cursed: false,
527	        }
528	    }
529	
530	    /// How many contracts the customer already holds when a quote is made: the
531	    /// standing the follow-up contract discount is judged against. The very
532	    /// first contract earns no discount; every later one does.
533	    const FIRST_CONTRACT: u32 = 0;
534	    const SECOND_CONTRACT: u32 = 1;
535	    const THIRD_CONTRACT: u32 = 2;
536	
537	    /// The premium the MHPCO quotes for a policy it can price. Every premium
538	    /// example below names a catalogued item, so the quote is always priced;
539	    /// the refusal channel is the subject of its own tests, not of these.
540	    fn premium_of(customer: &Customer, contracts_already_held: u32, items: &[Item]) -> u64 {
541	        quote_premium(customer, contracts_already_held, items).expect("the quote is priced")
542	    }
543	
544	    /// A group of `count` alike components, the shape the building-block
545	    /// offer is judged against.
546	    fn alike(count: usize, item_type: &str) -> Vec<Item> {
547	        (0..count).map(|_| plain(item_type)).collect()
548	    }
549	
550	    /// An incident reporting one damage per `(item type, amount)` pair, the
551	    /// shape a claim is filed as: the deductible is judged per damage entry,
552	    /// so each pair stands for one damage event.
553	    fn incident_of(damages: &[(&str, i64)]) -> Incident {
554	        Incident {
555	            damages: damages
556	                .iter()
557	                .map(|(item_type, amount)| Damage {
558	                    item_type: item_type.to_string(),
559	                    amount: *amount,
560	                })
561	                .collect(),
562	        }
563	    }
564	
565	    /// What the MHPCO pays when a policy covering just `item` is hit by a
566	    /// single damage of `amount` to that item: the shape every reimbursement
